export const run = async ({ args, files }) => {
  const patch = files["diff.patch"] || "";
  const lines = patch.split("\n");

  const fileStats = [];
  let currentFile = null;
  let currentAdded = 0;
  let currentRemoved = 0;
  let totalAdded = 0;
  let totalRemoved = 0;

  for (const line of lines) {
    if (line.startsWith("diff --git ")) {
      if (currentFile !== null) {
        fileStats.push({ path: currentFile, added: currentAdded, removed: currentRemoved });
        totalAdded += currentAdded;
        totalRemoved += currentRemoved;
      }
      currentFile = null;
      currentAdded = 0;
      currentRemoved = 0;
    } else if (line.startsWith("+++ b/")) {
      currentFile = line.slice(6);
    } else if (line.startsWith("--- a/") || line.startsWith("--- /dev/null")) {
      // ignore
    } else if (line.startsWith("+++")) {
      // ignore other +++ lines
    } else if (line.startsWith("+")) {
      currentAdded++;
    } else if (line.startsWith("-")) {
      currentRemoved++;
    }
  }

  if (currentFile !== null) {
    fileStats.push({ path: currentFile, added: currentAdded, removed: currentRemoved });
    totalAdded += currentAdded;
    totalRemoved += currentRemoved;
  }

  let stdout = "";
  for (const stat of fileStats) {
    stdout += `- [ ] ${stat.path} (+${stat.added} -${stat.removed})\n`;
  }
  stdout += `${fileStats.length} files, +${totalAdded} -${totalRemoved}\n`;

  return { stdout, files: {} };
};
